    const kd = 1 + ri(h - 2);
    door(kx, kd);
    for (let y = 1; y < h - 1; y++) if (y !== kd && rr() < 0.9) put(kx - 1, y, 'counter');
    put(kx + 1 + ri(2), 1, 'hearth');
    for (let i = 0; i < 5; i++) put(kx + 1 + ri(2), 1 + ri(h - 2), rr() < 0.5 ? 'barrel' : 'crate');
