  if (v === 'bestiaire' && BDIRTY) renderB();
  if (v === 'regles') rules();
  for (const a of document.querySelectorAll('.tabs a'))
    (a.toggleAttribute('aria-current', a.dataset.v === v), a.dataset.v === v && a.setAttribute('aria-current', 'page'));
