function parseAtk(txt) {
  const out = [],
    body = txt.replace(/^[^:]*?(Attacks?|Attaques?)\s*:\s*/i, '');
  const re = /([^·:;.,+\d][^·:;,+]*?)(?:\s*×\s*(\d+))?\s+([+-]\d+)\s*,\s*(\d+)d(\d+)\s*(?:([+-])\s*(\d+))?/g;
  let m;
  while ((m = re.exec(body))) {
    out.push({
      n: m[1].trim().replace(/^(Attacks?|Attaques?)\s*:\s*/i, ''),
      k: +(m[2] || 1),
      ab: +m[3],
      nd: +m[4],
      dd: +m[5],
      mod: m[6] ? (m[6] === '-' ? -1 : 1) * +m[7] : 0,
    });
  }
  return out;
}
