MP.uid = (() => {
  try {
    let u = sessionStorage.getItem('luparis-uid');
    if (!u) sessionStorage.setItem('luparis-uid', (u = Math.random().toString(36).slice(2, 10)));
    return u;
  } catch (e) {
    return Math.random().toString(36).slice(2, 10);
  }
})();
MP.local = /[?&]local=1/.test(location.search);
MP.prole = 'player';
